(()=>{'use strict';const es=document.documentElement.lang==='es',q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];const storage={get:(s,k)=>{try{return window[s].getItem(k)}catch{return null}},set:(s,k,v)=>{try{window[s].setItem(k,v)}catch{}}};storage.set('localStorage','mcs-language',es?'es':'en');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=storage.get('localStorage','mcs-motion')==='paused';const motion=q('.motion-toggle');function setMotion(){document.body.classList.toggle('motion-paused',paused);motion.textContent=paused?(es?'Activar movimiento':'Resume motion'):(es?'Pausar movimiento':'Pause motion');motion.setAttribute('aria-pressed',String(paused))}setMotion();motion.addEventListener('click',()=>{paused=!paused;storage.set('localStorage','mcs-motion',paused?'paused':'playing');setMotion()});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('page-hidden',document.hidden));
const firstVisit=!storage.get('sessionStorage','mcs-intro');storage.set('sessionStorage','mcs-intro','1');
const intro=q('.intro');let introPlaying=false;let introTimer;function finishIntro(){if(!intro||!intro.isConnected)return;clearTimeout(introTimer);introPlaying=false;document.body.classList.remove('intro-active');if(intro.contains(document.activeElement))q('.brand').focus();intro.hidden=true;intro.remove();window.dispatchEvent(new CustomEvent('mcs:intro-complete'));updateCta()}
if(intro){if(firstVisit&&!reduced.matches&&!paused){const mobile=innerWidth<=640,petals=intro.querySelector('.intro-petals');for(let i=0;i<(mobile?42:72);i++){const petal=document.createElement('i');petal.className='wind-petal';const seed=n=>((i*37+n*61)%101)/100;petal.style.cssText='--y:'+(-15+seed(1)*125)+'%;--size:'+(7+seed(2)*20)+'px;--rise:'+(-110+seed(3)*220)+'px;--flight:'+(mobile?2.2+seed(4)*.7:2.8+seed(4)*.8)+'s;--delay:'+(-.35+seed(5)*1.2)+'s;--alpha:'+(.35+seed(6)*.5)+';--blur:'+(i%6===0?'1.5px':'0px');petals.append(petal)}introPlaying=true;intro.hidden=false;document.body.classList.add('intro-active');q('.intro-skip').addEventListener('click',finishIntro);introTimer=setTimeout(finishIntro,mobile?3500:4400);setTimeout(finishIntro,5500);reduced.addEventListener('change',e=>{if(e.matches)finishIntro()})}else intro.remove()}
const toggle=q('.menu-toggle'),nav=q('#navigation');function closeMenu(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{const opened=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(opened));if(opened)nav.querySelector('a').focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){qa('.nav-drop[open]').forEach(d=>d.open=false);if(nav.classList.contains('open')){closeMenu();toggle.focus()}}});document.addEventListener('click',e=>{if(!e.target.closest('header')){closeMenu();qa('.nav-drop[open]').forEach(d=>d.open=false)}});qa('.nav-drop').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)qa('.nav-drop').filter(x=>x!==d).forEach(x=>x.open=false)}));
const cta=q('.mobile-cta'),initial=q('.initial-cta');let afterInitial=false;function updateCta(){const keyboard=window.visualViewport&&window.visualViewport.height<innerHeight*.72;const focused=/INPUT|SELECT|TEXTAREA/.test(document.activeElement?.tagName);cta.hidden=!afterInitial||introPlaying||keyboard||focused}if(initial){new IntersectionObserver(entries=>{const e=entries[0];afterInitial=!e.isIntersecting&&e.boundingClientRect.bottom<0;updateCta()},{threshold:0}).observe(initial)}addEventListener('scroll',()=>{document.body.classList.toggle('scrolled',scrollY>30)},{passive:true});window.visualViewport?.addEventListener('resize',updateCta);document.addEventListener('focusin',updateCta);document.addEventListener('focusout',()=>setTimeout(updateCta,100));
const form=q('.inquiry');if(form){const radios=[...form.querySelectorAll('[name=service]')];const selected=()=>radios.find(r=>r.checked).value;const update=()=>{form.querySelectorAll('[data-for]').forEach(el=>{el.hidden=!el.dataset.for.split(' ').includes(selected());el.querySelectorAll('input,select,textarea').forEach(input=>input.disabled=el.hidden)})};radios.forEach(r=>r.addEventListener('change',update));const requested=new URLSearchParams(location.search).get('service');if(requested){const radio=radios.find(r=>r.value===requested);if(radio)radio.checked=true}update();form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),labels=es?{service:'Servicio',name:'Nombre',phone:'Teléfono',location:'Ubicación',destination:'Destino',vehicle:'Vehículo',year:'Año',car:'Marca y modelo',running:'Estado',title:'Título',start:'Inicio',end:'Regreso',use:'Uso',details:'Detalles'}:{service:'Service',name:'Name',phone:'Phone',location:'Location',destination:'Destination',vehicle:'Vehicle',year:'Year',car:'Make and model',running:'Condition',title:'Title',start:'Start',end:'Return',use:'Use',details:'Details'};let msg='MCS 86 Towing\n';for(const [k,v]of data){if(v.trim())msg+=labels[k]+': '+(k==='service'?radios.find(r=>r.checked).nextElementSibling.textContent:v)+'\n'}const box=form.querySelector('.message-fallback');box.hidden=false;box.querySelector('textarea').value=msg;form.querySelector('.form-status').textContent=es?'Mensaje preparado. Envíalo desde tu aplicación; aún no se ha enviado nada.':'Message prepared. Send it from your messaging app; nothing has been sent yet.';location.href='sms:+19098276022?body='+encodeURIComponent(msg)})}
const dialog=q('.lightbox');let current=0,opener;const photos=qa('[data-photo]');const items=[1,2,3,4,5,6].map(n=>{const im=q(`[data-photo="${n}"] img`);return{src:'/assets/photo-'+n+'.jpg',alt:im?.alt||''}});function showPhoto(i){current=(i+6)%6;const item=items[current],img=dialog.querySelector('img');img.src=item.src;img.alt=item.alt;dialog.querySelector('figcaption').textContent=item.alt;dialog.querySelector('.photo-count').textContent=(current+1)+' / 6'}photos.forEach(btn=>btn.addEventListener('click',()=>{opener=btn;showPhoto(Number(btn.dataset.photo)-1);dialog.showModal();dialog.querySelector('.lightbox-close').focus()}));dialog.querySelector('.lightbox-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>opener?.focus());dialog.querySelector('.photo-prev').addEventListener('click',()=>showPhoto(current-1));dialog.querySelector('.photo-next').addEventListener('click',()=>showPhoto(current+1));dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showPhoto(current-1)}if(e.key==='ArrowRight'){e.preventDefault();showPhoto(current+1)}});let touchX;dialog.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});dialog.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>45)showPhoto(current+(delta<0?1:-1))},{passive:true});dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
})();
